  function render(md) {
    let raw = String(md || '').replace(/\r\n/g, '\n').trim();
    const lines = raw.split('\n');
    const out = [];
    let inList = false;

    function closeList() {
      if (inList) { out.push('</ul>'); inList = false; }
    }

    for (let i = 0; i < lines.length; i++) {
      const line = lines[i].trim();
      if (!line) {
        closeList();
        continue;
      }

      if (line.startsWith('### ')) {
        closeList();
        out.push(`<h3>${line.slice(4)}</h3>`);
        continue;
      }
      if (line.startsWith('## ')) {
        closeList();
        out.push(`<h2>${line.slice(3)}</h2>`);
        continue;
      }
      if (line.startsWith('# ')) {
        closeList();
        out.push(`<h1>${line.slice(2)}</h1>`);
        continue;
      }
      if (line.startsWith('> ')) {
        closeList();
        out.push(`<blockquote>${line.slice(2)}</blockquote>`);
        continue;
      }
      if (line.startsWith('<div class="meta">') || line.startsWith('<div class="callout">')) {
        closeList();
        out.push(line);
        continue;
      }

      if (/^[-*•]\s+/.test(line)) {
        if (!inList) {
          out.push('<ul class="ai-bullet-list">');
          inList = true;
        }
        out.push(`<li>${line.replace(/^[-*•]\s+/, '')}</li>`);
        continue;
      }

      closeList();
      out.push(`<p>${line}</p>`);
    }
    closeList();

    return out.join('\n')
      .replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>')
      .replace(/`([^`]+)`/g, '<code>$1</code>')
      .replace(/\[([^\]]+)\]\(([^)]+)\)/g, (match, label, target) => {
        return files[target]
          ? `<a href="#${target}" data-file="${target}">${label}</a>`
          : `<a href="${target}" target="_blank" rel="noreferrer">${label} ↗</a>`;
      });
  }

  const tree = [...document.querySelectorAll('.tree-file')];
